// P4 phase 2 (T160): SVG fallback engine moved VERBATIM from MapView.tsx —
// dependency-free renderer used when engine === 'svg' (WebGL-less/VM browsers).
import { useEffect, useMemo, useState } from 'react';
import type { MapViewProps as FallbackProps } from './mapViewTypes';
import { circuityColor } from '../lib/circuityColor';
import { PROPOSED_DEFAULT_COLOR, PROPOSED_MUTED_COLOR, routePalette } from '../lib/mapLayers';
import { ONE_WAY_COLOR, SHIFT_EARLIER_COLOR, SHIFT_LATER_COLOR } from './mapViewTypes';

/* ------------------------------------------------------------------ */
/* SVG fallback renderer — dependency-free, works everywhere          */
/* ------------------------------------------------------------------ */

const DEFAULT_BOUNDS = { minLon: -79.9, maxLon: -79.35, minLat: 43.5, maxLat: 43.72 };

function project(lon: number, lat: number, bounds: typeof DEFAULT_BOUNDS, w: number, h: number) {
  const x = ((lon - bounds.minLon) / (bounds.maxLon - bounds.minLon)) * w;
  const y = ((bounds.maxLat - lat) / (bounds.maxLat - bounds.minLat)) * h;
  return [x, y] as const;
}

export default function FallbackSvg({
  circuity,
  nodes,
  showRoutes,
  showSplits,
  showNodes,
  showOneWay,
  highlightedRoute,
  travelLines = [],
  travelMarkers = [],
  onMapPick,
  pickActive = false,
  showProposedNetwork = false,
  optimizeShifts = [],
}: FallbackProps) {
  const W = 900;
  const H = 560;
  const [bounds, setBounds] = useState<typeof DEFAULT_BOUNDS | null>(null);

  useEffect(() => {
    if (!circuity) return;
    let minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity;
    circuity.features.forEach((f) => {
      f.geometry.coordinates.forEach(([lon, lat]) => {
        if (lon < minLon) minLon = lon;
        if (lon > maxLon) maxLon = lon;
        if (lat < minLat) minLat = lat;
        if (lat > maxLat) maxLat = lat;
      });
    });
    nodes.forEach((n) => {
      if (n.lon < minLon) minLon = n.lon;
      if (n.lon > maxLon) maxLon = n.lon;
      if (n.lat < minLat) minLat = n.lat;
      if (n.lat > maxLat) maxLat = n.lat;
    });
    const padLon = (maxLon - minLon) * 0.05 || 0.02;
    const padLat = (maxLat - minLat) * 0.05 || 0.02;
    if (!Number.isFinite(minLon) || !Number.isFinite(maxLon)) {
      // No geometry at all (empty FeatureCollection, no nodes): fall back to
      // the default city bounds instead of projecting onto NaN.
      setBounds(null);
      return;
    }
    setBounds({ minLon: minLon - padLon, maxLon: maxLon + padLon, minLat: minLat - padLat, maxLat: maxLat + padLat });
  }, [circuity, nodes]);

  const b = bounds ?? DEFAULT_BOUNDS;
  const point = (lon: number, lat: number) => project(lon, lat, b, W, H);

  const palette = useMemo(
    () =>
      routePalette(
        (circuity?.features ?? [])
          .filter((f) => f.properties.flagged && f.properties.proposed_split)
          .map((f) => f.properties.route_short_name)
      ),
    [circuity]
  );

  const onSvgClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!onMapPick) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * W;
    const y = ((e.clientY - rect.top) / rect.height) * H;
    const lon = b.minLon + (x / W) * (b.maxLon - b.minLon);
    const lat = b.maxLat - (y / H) * (b.maxLat - b.minLat);
    onMapPick(lat, lon);
  };

  const gridLines: JSX.Element[] = [];
  for (let i = 0; i <= 9; i++) {
    const x = (W / 9) * i;
    gridLines.push(<line key={`v${i}`} x1={x} y1={0} x2={x} y2={H} stroke="#d8dde3" strokeWidth={1} />);
    const y = (H / 7) * i;
    gridLines.push(<line key={`h${i}`} x1={0} y1={y} x2={W} y2={y} stroke="#d8dde3" strokeWidth={1} />);
  }

  return (
    <div className={`relative h-full w-full overflow-hidden bg-[#f3f4f6] ${pickActive ? 'cursor-crosshair' : ''}`}>
      <svg viewBox={`0 0 ${W} ${H}`} className="h-full w-full" preserveAspectRatio="xMidYMid meet" onClick={onSvgClick}>
        {gridLines}
        {showRoutes &&
          circuity?.features
            // In proposed-network mode today's routes are not drawn at all;
            // the trunk + feeder lines below are the network.
            .filter(() => !showProposedNetwork)
            .map((f, i) => {
              const d = f.geometry.coordinates
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              const baseOpacity = showProposedNetwork ? 0.15 : optimizeShifts.length > 0 ? 0.08 : 1;
              return (
                <g key={`r-${i}`}>
                  {/* dark casing so the vivid line reads on light/muted basemaps */}
                  <path
                    d={d}
                    fill="none"
                    stroke="#233244"
                    strokeWidth={5}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    opacity={baseOpacity * 0.55}
                  />
                  <path
                    d={d}
                    fill="none"
                    stroke={circuityColor(f.properties.circuity)}
                    strokeWidth={2.6}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    opacity={baseOpacity}
                  />
                </g>
              );
            })}
        {showSplits &&
          circuity?.features
            .filter((f) => f.properties.flagged && f.properties.proposed_split)
            .flatMap((f) => {
              const p = f.properties.proposed_split!;
              const color = palette.get(f.properties.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const route = f.properties.route_short_name;
              const parts: {
                part: 'trunk' | 'branch';
                coords: [number, number][];
                color: string;
                route: string;
              }[] = [
                { part: 'trunk', coords: p.trunk_geometry, color, route },
              ];
              p.branches.forEach((b) => parts.push({ part: 'branch', coords: b.geometry, color, route }));
              return parts;
            })
            .map(({ part, coords, color, route }, i) => {
              // Focus mode: unselected candidates draw muted grey; the selected
              // route pops in its hue. Show-all mode: every route in its hue,
              // selected pops via weight.
              const hl = highlightedRoute != null && route === highlightedRoute;
              const effColor = showProposedNetwork
                ? color
                : hl
                  ? color
                  : PROPOSED_MUTED_COLOR;
              const effOpacity = showProposedNetwork
                ? highlightedRoute != null
                  ? hl
                    ? 1
                    : 0.55
                  : 1
                : hl
                  ? 1
                  : 0.4;
              const effWeight = showProposedNetwork || hl
                ? part === 'trunk'
                  ? 5
                  : 3.5
                : part === 'trunk'
                  ? 3
                  : 2.5;
              const d = coords
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              return (
                <path
                  key={`s-${part}-${i}`}
                  d={d}
                  fill="none"
                  stroke={effColor}
                  strokeWidth={effWeight}
                  opacity={effOpacity}
                  strokeDasharray={part === 'branch' ? '6 5' : undefined}
                  strokeLinecap="round"
                />
              );
            })}
        {showSplits &&
          circuity?.features
            .filter((f) => f.properties.flagged && f.properties.proposed_split?.splice_junctions?.length)
            // Focus mode: only the selected route's dots draw, so the map
            // stays uncluttered; show-all mode draws every splice's dots.
            .filter(
              (f) =>
                showProposedNetwork ||
                (highlightedRoute != null &&
                  f.properties.route_short_name === highlightedRoute)
            )
            .flatMap((f) => {
              const color = palette.get(f.properties.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const p = f.properties.proposed_split!;
              return p.splice_junctions!.map((j, k) => ({
                key: `j-${f.properties.route_short_name}-${k}`,
                color,
                j,
                k,
                route: f.properties.route_short_name,
                donor: p.donor_route,
              }));
            })
            .map(({ key, color, j, k, route, donor }) => {
              const [x, y] = point(j.lon, j.lat);
              return (
                <g key={key}>
                  <circle cx={x} cy={y} r={7} fill="#ffffff" stroke={color} strokeWidth={2.5} />
                  <circle cx={x} cy={y} r={4.5} fill={color} />
                  <title>{`Route ${route} — ${k === 0 ? 'leaves' : 'rejoins'} Route ${donor}'s routing: ${j.label}`}</title>
                </g>
              );
            })}
        {(showProposedNetwork || highlightedRoute != null) &&
          circuity?.features
            .filter((f) => f.properties.flagged && f.properties.proposed_split)
            // Focus mode labels only the selected route; show-all labels all.
            .filter(
              (f) =>
                showProposedNetwork ||
                f.properties.route_short_name === highlightedRoute
            )
            .flatMap((f) => {
              const p = f.properties.proposed_split!;
              const color = palette.get(f.properties.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const labels: { label: string; color: string; coords: [number, number][]; solid: boolean }[] = [
                { label: f.properties.route_short_name, color, coords: p.trunk_geometry, solid: true },
              ];
              p.branches.forEach((b, i) =>
                labels.push({
                  label: `${f.properties.route_short_name}${String.fromCharCode(65 + i)}`,
                  color,
                  coords: b.geometry,
                  solid: false,
                })
              );
              return labels;
            })
            .map(({ label, color, coords, solid }, i) => {
              if (coords.length < 2) return null;
              const mid = coords[Math.floor(coords.length / 2)];
              const [x, y] = point(mid[0], mid[1]);
              return solid ? (
                <g key={`pl-${i}`}>
                  <rect
                    x={x - 11}
                    y={y - 8}
                    width={22}
                    height={16}
                    rx={8}
                    fill={color}
                  />
                  <text
                    x={x}
                    y={y + 3.5}
                    textAnchor="middle"
                    fontSize={9.5}
                    fontWeight={700}
                    fill="#ffffff"
                  >
                    {label}
                  </text>
                </g>
              ) : (
                <g key={`pl-${i}`}>
                  <rect
                    x={x - 12}
                    y={y - 8}
                    width={24}
                    height={16}
                    rx={6}
                    fill="rgba(255,255,255,0.95)"
                    stroke={color}
                    strokeWidth={1.5}
                  />
                  <text
                    x={x}
                    y={y + 3.5}
                    textAnchor="middle"
                    fontSize={9.5}
                    fontWeight={700}
                    fill={color}
                  >
                    {label}
                  </text>
                </g>
              );
            })}
        {showOneWay &&
          circuity?.features
            .filter((f) => f.properties.one_way)
            .map((f, i) => {
              const coords = f.geometry.coordinates;
              const d = coords
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              const step = Math.max(1, Math.floor(coords.length / 6));
              const arrows = [];
              for (let j = 0; j < coords.length - 1; j += step) {
                const a = coords[j];
                const b = coords[Math.min(j + 1, coords.length - 1)];
                const [ax, ay] = point(a[0], a[1]);
                const [bx, by] = point(b[0], b[1]);
                const mx = (ax + bx) / 2;
                const my = (ay + by) / 2;
                const ang = (Math.atan2(by - ay, bx - ax) * 180) / Math.PI;
                arrows.push(
                  <g key={j} transform={`translate(${mx.toFixed(1)},${my.toFixed(1)}) rotate(${ang.toFixed(1)})`}>
                    <path d="M-6,-4 L4,0 L-6,4" fill="none" stroke={ONE_WAY_COLOR} strokeWidth={2} />
                  </g>
                );
              }
              return (
                <g key={`ow-${i}`}>
                  <path
                    d={d}
                    fill="none"
                    stroke={ONE_WAY_COLOR}
                    strokeWidth={3}
                    strokeDasharray="8 6"
                    strokeLinecap="round"
                  />
                  {arrows}
                </g>
              );
            })}
        {showNodes &&
          nodes.map((n) => {
            const [x, y] = point(n.lon, n.lat);
            const r = 3 + n.friction_score * 0.3;
            const color = n.friction_score > 30 ? '#FF5252' : n.friction_score > 20 ? '#FFB300' : '#00E676';
            return (
              <g key={n.stop_id}>
                <circle cx={x} cy={y} r={r} fill={color} opacity={0.95} stroke="#1f2937" strokeWidth={1} />
                <title>{`${n.stop_name} — friction ${n.friction_score}`}</title>
              </g>
            );
          })}
        {travelLines.map((line) => {
          const d = line.points
            .map(([lat, lon], j) => {
              const [x, y] = point(lon, lat);
              return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
            })
            .join(' ');
          return (
            <path
              key={`tl-${line.id}`}
              d={d}
              fill="none"
              stroke={line.color}
              strokeWidth={line.weight ?? 5}
              strokeDasharray={line.dashArray}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          );
        })}
        {optimizeShifts.length > 0 &&
          optimizeShifts
            .map((s) => {
              const f = circuity?.features.find(
                (x) => x.properties.route_short_name === s.route_short_name
              );
              if (!f) return null;
              const earlier = s.offset_minutes < 0;
              const color = earlier ? SHIFT_EARLIER_COLOR : SHIFT_LATER_COLOR;
              const d = f.geometry.coordinates
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              const mid = f.geometry.coordinates[Math.floor(f.geometry.coordinates.length / 2)];
              const [mx, my] = point(mid[0], mid[1]);
              return {
                key: s.route_short_name,
                d,
                color,
                weight: 2.5 + Math.min(4, Math.abs(s.offset_minutes)),
                label: `R${s.route_short_name} ${earlier ? '-' : '+'}${Math.abs(s.offset_minutes)}m`,
                mx,
                my,
              };
            })
            .filter(
              (o): o is {
                key: string;
                d: string;
                color: string;
                weight: number;
                label: string;
                mx: number;
                my: number;
              } => o !== null
            )
            .map((o) => (
              <g key={o.key}>
                <path
                  d={o.d}
                  fill="none"
                  stroke={o.color}
                  strokeWidth={o.weight}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
                <g transform={`translate(${o.mx.toFixed(1)},${o.my.toFixed(1)})`}>
                  <rect x={-14} y={-8} width={28} height={16} rx={8} fill={o.color} />
                  <text
                    x={0}
                    y={3.5}
                    textAnchor="middle"
                    fontSize={9.5}
                    fontWeight={700}
                    fill="#ffffff"
                  >
                    {o.label}
                  </text>
                </g>
              </g>
            ))}
        {travelMarkers.map((m) => {
          const [x, y] = point(m.lon, m.lat);
          return (
            <g key={`tm-${m.id}`}>
              <circle cx={x} cy={y} r={7} fill={m.color} stroke="#ffffff" strokeWidth={2} />
              <title>{m.label}</title>
            </g>
          );
        })}
      </svg>
      <div className="absolute left-2 top-2 rounded bg-white/90 px-2 py-1 text-[10px] text-slate-700 shadow-sm">
        SVG preview
      </div>
      {!circuity && (
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="rounded bg-white/90 px-3 py-1.5 text-sm text-slate-600 shadow-sm">
            Loading route geometry…
          </span>
        </div>
      )}
    </div>
  );
}
