import { useEffect, useMemo, useRef, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import BasemapPicker from './BasemapPicker';
import { basemapById, defaultBasemapId } from '../lib/basemaps';
import FallbackSvg from './FallbackSvg';
import useLeafletMap from './useLeafletMap';
import { circuityColor } from '../lib/circuityColor';
import { api } from '../lib/api';
import type { EquityReport } from '../types';
import {
  PROPOSED_DEFAULT_COLOR,
  PROPOSED_MUTED_COLOR,
  routePalette,
  routeStroke,
  bearingDeg,
  LEGEND_STOPS,
  buildSplitFeatures,
} from '../lib/mapLayers';
import type { MapViewProps } from './mapViewTypes';
import { INITIAL_ZOOM, NODE_MIN_ZOOM, ONE_WAY_COLOR, SHIFT_EARLIER_COLOR, SHIFT_LATER_COLOR } from './mapViewTypes';

// P4 phase 2: shared map types live in mapViewTypes.ts; re-exported so
// external consumers keep importing them from './MapView'.
export type { MapEngine, TravelLine, TravelMarker, OptimizeShift, MapViewProps as Props } from './mapViewTypes';

/**
 * Main interactive map built on Leaflet (pure DOM — no WebGL required, so it
 * works on ARM64 / VM / remote-desktop browsers where WebGL maps go black).
 *
 * Basemap: swappable via the picker (Esri Light Gray by default, A18 — a
 * calm grey canvas that lets the circuity-colored routes lead). Route/node
 * overlays sit above real roads instead of a grey void.
 *
 * The route / split / node layers are drawn from the route GeoJSON itself, so
 * they render even if the tile host is unreachable. If tiles can't load the
 * map just shows routes on a light background.
 */

// Map-view constants (CENTER/zoom tiers/one-way + shift colors) live in
// mapViewTypes.ts (P4 phase 2). Layer styling math lives in ../lib/mapLayers.

/**
 * Apply the split layer's mode-aware styling to every polyline.
 *
 * Focus mode (showAll = false): unselected proposals draw in a single muted
 * grey (thin, translucent) so the map reads as one calm set of candidates;
 * the selected route pops in its own hue with trunk solid + feeders dashed.
 * Show-all mode: every proposal draws in its own hue; the selected route
 * pops via weight. Kept as one helper so the layer is styled the same right
 * after (re)building it and on every selection / mode change.
 */
function styleSplitLayer(
  layer: L.GeoJSON,
  showAll: boolean,
  highlightedRoute: string | null
) {
  layer.eachLayer((l) => {
    const props = (l as L.Polyline).feature?.properties as
      | { route?: string; part?: string; color?: string }
      | undefined;
    if (!props?.route) return;
    const branch = props.part === 'branch';
    const color = props.color ?? PROPOSED_DEFAULT_COLOR;
    const hl = highlightedRoute != null && props.route === highlightedRoute;
    if (showAll) {
      (l as L.Path).setStyle({
        color,
        weight: hl ? (branch ? 5 : 7) : branch ? 3.5 : 5,
        opacity: highlightedRoute != null ? (hl ? 1 : 0.55) : 1,
        dashArray: branch ? '6 5' : undefined,
      });
      return;
    }
    if (hl) {
      (l as L.Path).setStyle({
        color,
        weight: branch ? 3.5 : 5,
        opacity: 1,
        dashArray: branch ? '6 5' : undefined,
      });
    } else {
      (l as L.Path).setStyle({
        color: PROPOSED_MUTED_COLOR,
        weight: branch ? 2.5 : 3,
        opacity: 0.4,
        dashArray: branch ? '6 5' : undefined,
      });
    }
  });
}

/** Build a leaflet DivIcon: a small arrow rotated to a heading. */
function directionIcon(deg: number, color = ONE_WAY_COLOR): L.DivIcon {
  const html = `<svg width="16" height="16" viewBox="0 0 16 16" style="transform:rotate(${deg}deg)">
    <path d="M8 2 L14 8 L8 14 M14 8 H0" stroke="${color}" stroke-width="2" fill="none"
      stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
  return L.divIcon({ html, className: 'route-direction-arrow', iconSize: [16, 16], iconAnchor: [8, 8] });
}

export default function MapView({
  circuity,
  nodes,
  showRoutes,
  showSplits,
  showNodes,
  showOneWay = false,
  highlightedRoute,
  engine = 'auto',
  travelLines = [],
  travelMarkers = [],
  onMapPick,
  pickActive = false,
  showProposedNetwork = false,
  optimizeShifts = [],
  corridorSeam = null,
}: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  // One distinct hue per proposed route (trunk + branch share it).
  const proposalColors = useMemo(
    () =>
      routePalette(
        (circuity?.features ?? [])
          .filter((f) => f.properties.flagged && f.properties.proposed_split)
          .map((f) => f.properties.route_short_name)
      ),
    [circuity]
  );
const [tileNote, setTileNote] = useState<string | null>(null);
// Hover-to-isolate: pointing at a route dims the rest of the network so it
// can be traced without clicking. Explicit panel selection overrides it.
const [hoverRoute, setHoverRoute] = useState<string | null>(null);
// Zoom level drives routeStroke(); synced from the map's zoomend below.
const [zoomLevel, setZoomLevel] = useState(INITIAL_ZOOM);
// Active basemap (defaults from localStorage, updated by the picker).
const [basemapId, setBasemapId] = useState(defaultBasemapId);
const basemap = basemapById(basemapId);

// Ward equity overlay — scores derive from the equity report in the effect
// below; the map layer colors from wardScores only.
const [wardBoundaries, setWardBoundaries] = useState<GeoJSON.FeatureCollection<GeoJSON.Polygon | GeoJSON.MultiPolygon> | null>(null);
const [wardScores, setWardScores] = useState<Record<string, number>>({});
const [showWardScores, setShowWardScores] = useState(false);
// T159 #1: true when the boundaries GeoJSON failed to load — the toggle then
// shows 'unavailable' instead of flipping to 'on' with zero visual change.
const [wardLayerError, setWardLayerError] = useState(false);

  const useLeaflet = engine !== 'svg';

  // P4 phase 2: Leaflet lifecycle + layer refs live in the hook; the
  // returned refs keep their original names, so every effect below is
  // verbatim pre-split text.
  const {
    mapRef,
    routeLayerRef,
    splitLayerRef,
    nodeLayerRef,
    oneWayLayerRef,
    travelLayerRef,
    seamLayerRef,
    shiftLayerRef,
    proposedLabelLayerRef,
    wardLayerRef,
  } = useLeafletMap({ useLeaflet, containerRef, basemap, wardScores, setZoomLevel, setBasemapId, setTileNote });

   // Fetch equity report data (same as EquityPanel)
   useEffect(() => {
     if (!useLeaflet) return;

     let cancelled = false;

     const loadEquityData = async () => {
       try {
         // Try the on-the-fly compute endpoint first (uses latest optimizer run).
         // Falls back to the file-based report if no optimization has been run.
         let d: EquityReport;
         try {
           d = await api.equityCompute();
         } catch {
           d = await api.equityReport();
         }
        if (!cancelled) {
          // Extract ward scores from the equity report
           if (d?.wards?.rows) {
             const scores: Record<string, number> = {};
             for (const ward of d.wards.rows) {
               scores[ward.ward] = ward.delta_minutes;
             }
             setWardScores(scores);
           }
         }
       } catch (e) {
         console.error('Failed to load equity data:', e);
         // Silently fail - we don't want to spam the UI with errors for an optional overlay
       }
     };

     void loadEquityData();

     return () => {
       cancelled = true;
     };
   }, [useLeaflet]);

   // Load ward boundaries GeoJSON
   useEffect(() => {
     if (!useLeaflet) return;

     let cancelled = false;

     const loadWardBoundaries = async () => {
       try {
         // Base-relative so the Pages build (served under /miway-transit-optimizer/)
         // hits the bundled file, not the SPA fallback. The file ships in
         // frontend/public/data/ (copied from backend/app/data/downloads/ —
         // T159 #1: the old '/app/data/...' path hit the SPA's index.html and
         // the toggle pretended success).
         const geojsonUrl = `${import.meta.env.BASE_URL ?? '/'}data/mississauga_ward_boundaries.geojson`;
         const response = await fetch(geojsonUrl);
         if (!response.ok) {
           throw new Error(`Failed to load ward boundaries: ${response.status}`);
         }
         const geojson = await response.json();
         if (!cancelled && geojson.type === 'FeatureCollection') {
           setWardBoundaries(geojson);
         } else if (!cancelled) {
           console.warn('Ward boundaries fetch returned non-FeatureCollection payload');
           setWardLayerError(true);
         }
       } catch (e) {
         console.warn('Could not load ward boundaries GeoJSON:', e);
         // Surface failure instead of pretending success (T159 #1): the
         // toggle must tell the rider the overlay is unavailable.
         if (!cancelled) setWardLayerError(true);
       }
     };

     void loadWardBoundaries();

     return () => {
       cancelled = true;
     };
   }, [useLeaflet]);

  // ---- route overlay (GeoJSON, styled by circuity) --------------------
  // Each route draws twice: a dark casing underneath (a thin slate outline,
  // barely visible) plus the vivid circuity-colored line on top. The casing
  // keeps every route legible on light/muted basemaps (e.g. Humanitarian),
  // where thin colored lines — especially the mid-gradient yellow — wash out.
  // Both polylines carry the route's `.feature` so the highlight / dimming
  // effect below styles them together; the casing is flagged `isCasing`.
  useEffect(() => {
    const layer = routeLayerRef.current;
    if (!layer || !circuity) return;
    const stroke = routeStroke(zoomLevel);
    layer.clearLayers();
    circuity.features.forEach((f) => {
      const coords = f.geometry.coordinates;
      if ((coords as Array<unknown>).length < 2) return;
      const latlngs = coords.map(([lon, lat]) => [lat, lon] as L.LatLngTuple);

      const casing = L.polyline(latlngs, {
        color: '#233244',
        weight: stroke.casing,
        opacity: stroke.casingOpacity,
        interactive: false,
      });
      (casing as unknown as { feature?: GeoJSON.Feature }).feature = f;
      (casing as unknown as { isCasing?: boolean }).isCasing = true;
      casing.addTo(layer);

      const line = L.polyline(latlngs, {
        color: circuityColor(f.properties.circuity),
        weight: stroke.line,
        opacity: 0.95,
      });
      (line as unknown as { feature?: GeoJSON.Feature }).feature = f;
      line.bindPopup(`<strong>Route ${f.properties.route_short_name}</strong>`);
      line.bindTooltip(`Route ${f.properties.route_short_name}`, {
        sticky: true,
        direction: 'top',
        opacity: 0.9,
      });
      line.on('mouseover', () => setHoverRoute(f.properties.route_short_name));
      line.on('mouseout', () => setHoverRoute(null));
      line.addTo(layer);
    });
  }, [circuity, useLeaflet, zoomLevel]);

  useEffect(() => {
    const layer = routeLayerRef.current;
    if (!layer) return;
    if (showRoutes) {
      if (!mapRef.current?.hasLayer(layer)) layer.addTo(mapRef.current!);
    } else {
      mapRef.current?.removeLayer(layer);
    }
  }, [showRoutes, useLeaflet]);

  // ---- split branch overlay -------------------------------------------
  // In focus mode (showProposedNetwork off) unselected proposals draw muted
  // grey and only the selected route shows its own hue, badges and junction
  // dots — the map stays calm and each route is read one at a time. In
  // show-all mode every proposal draws in its own hue with badges.
  const isSelected = (route: string) =>
    highlightedRoute != null && highlightedRoute === route;

  useEffect(() => {
    const layer = splitLayerRef.current;
    if (!layer || !circuity) return;
    layer.clearLayers();
    // Split features built by the pure helper (P4 phase 1, unit-tested).
    const features = buildSplitFeatures(circuity, proposalColors);
    if (features.length) layer.addData({ type: 'FeatureCollection', features } as GeoJSON.GeoJsonObject);

    // Apply the mode-aware style immediately after (re)building the layer, so
    // a fresh circuity load is never left in the wrong style.
    styleSplitLayer(layer, showProposedNetwork, highlightedRoute ?? null);

    // Junction dots for corridor splices: the route leaves the donor corridor
    // at the first point and rejoins it at the second (the branch's endpoints
    // are exactly those two junctions). Hover for the stop name. In focus
    // mode only the selected route's dots draw, so the map stays uncluttered.
    circuity.features.forEach((f) => {
      const p = f.properties;
      const split = p.proposed_split;
      if (!p.flagged || !split?.splice_junctions?.length) return;
      if (!showProposedNetwork && !isSelected(p.route_short_name)) return;
      const color = proposalColors.get(p.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
      split.splice_junctions.forEach((j, k) => {
        const circle = L.circleMarker([j.lat, j.lon], {
          radius: 7,
          color: '#ffffff',
          weight: 2.5,
          fillColor: color,
          fillOpacity: 1,
        });
        circle.bindTooltip(
          `<strong>Route ${p.route_short_name}</strong> — ${k === 0 ? 'leaves' : 'rejoins'} Route ${split.donor_route}'s routing<br/>${j.label}`,
          { direction: 'top' }
        );
        circle.addTo(layer);
      });
    });
  }, [circuity, proposalColors, showProposedNetwork, highlightedRoute, useLeaflet]);

  useEffect(() => {
    const layer = splitLayerRef.current;
    if (!layer) return;
    if (showSplits) {
      if (!mapRef.current?.hasLayer(layer)) layer.addTo(mapRef.current!);
    } else {
      mapRef.current?.removeLayer(layer);
    }
  }, [showSplits, useLeaflet]);

  // ---- one-way (single direction) route overlay ------------------------
  useEffect(() => {
    const group = oneWayLayerRef.current;
    if (!group) return;
    group.clearLayers();
    if (!showOneWay || !circuity) return;

    circuity.features.forEach((f) => {
      if (!f.properties.one_way) return;
      const coords = f.geometry.coordinates as [number, number][];
      if (coords.length < 2) return;
      const latlngs = coords.map(([lon, lat]) => [lat, lon] as L.LatLngTuple);

      const line = L.polyline(latlngs, {
        color: ONE_WAY_COLOR,
        weight: 3,
        dashArray: '8 6',
        opacity: 0.95,
      });
      line.bindPopup(
        `<strong>Route ${f.properties.route_short_name}</strong><br/>Runs one way only in this period`
      );
      line.addTo(group);

      // direction arrows at evenly spaced points along the shape
      const step = Math.max(1, Math.floor(latlngs.length / 6));
      for (let i = 0; i < latlngs.length - 1; i += step) {
        const a = coords[i];
        const b = coords[Math.min(i + 1, coords.length - 1)];
        const mid: [number, number] = [
          (latlngs[i][0] + latlngs[i + 1][0]) / 2,
          (latlngs[i][1] + latlngs[i + 1][1]) / 2,
        ];
        L.marker(mid, {
          icon: directionIcon(bearingDeg(a, b)),
          interactive: false,
        }).addTo(group);
      }
    });
  }, [circuity, showOneWay, useLeaflet]);

  // ---- transfer stop nodes --------------------------------------------
  useEffect(() => {
    const group = nodeLayerRef.current;
    if (!group) return;
    group.clearLayers();
    nodes.forEach((n) => {
      const color = n.friction_score > 30 ? '#FF5252' : n.friction_score > 20 ? '#FFB300' : '#00E676';
      // Small dots, visible only once the user zooms in past the overview zoom.
      const radius = 2 + n.friction_score * 0.12;
      const marker = L.circleMarker([n.lat, n.lon], {
        radius,
        color: '#1f2937',
        weight: 1,
        fillColor: color,
        fillOpacity: 0.95,
      });
      marker.bindPopup(
        `<strong>${n.stop_name}</strong><br/>Routes: ${n.routes.join(', ')}<br/>Friction: ${n.friction_score.toFixed(1)} / 50`
      );
      marker.addTo(group);
    });
  }, [nodes, useLeaflet]);

  useEffect(() => {
    const group = nodeLayerRef.current;
    const map = mapRef.current;
    if (!group || !map) return;

    const sync = () => {
      const visible = showNodes && map.getZoom() >= NODE_MIN_ZOOM;
      if (visible) {
        if (!map.hasLayer(group)) group.addTo(map);
      } else {
        map.removeLayer(group);
      }
    };

    sync();
    map.on('zoomend', sync);
    return () => {
      map.off('zoomend', sync);
    };
  }, [showNodes, useLeaflet]);

  // ---- highlight a specific route -------------------------------------
  useEffect(() => {
    const layer = routeLayerRef.current;
    if (!layer) return;
    // Hover isolates gently (0.3) so a stray mouse pass never blanks the map;
    // an explicit panel selection isolates hard (0.12) and always wins.
    const focusRoute = highlightedRoute ?? hoverRoute;
    const hoverOnly = highlightedRoute == null && hoverRoute != null;
    const stroke = routeStroke(zoomLevel);
    // In proposed-network mode the current network no longer exists as drawn:
    // every route with a proposal is replaced by its trunk + feeder lines, and
    // the rest of today's network fades away too, so the map shows only the
    // redesigned network. Toggle the view off to compare with today's routes.
    layer.eachLayer((l) => {
      const cast = l as L.Path & {
        feature?: { properties?: { route_short_name?: string } };
        isCasing?: boolean;
      };
      const isCasing = !!cast.isCasing;
      const props = cast.feature?.properties;
      const route = props?.route_short_name;
      if (route == null) return;
      if (showProposedNetwork) {
        cast.setStyle({ opacity: 0 });
        return;
      }
      // Optimizer re-phase view: the whole base network steps back and the
      // shift overlay carries the moved routes, so only it should pop.
      if (optimizeShifts.length > 0) {
        cast.setStyle({ weight: isCasing ? stroke.casing : stroke.line, opacity: 0.08 });
        return;
      }
      const hl = focusRoute != null && route === focusRoute;
      // A19 (2026-09-27): with no interaction at city-overview zoom, all 57
      // routes at 0.95 opacity read as saturated spaghetti — the map had no
      // visual default short of hover (which had no affordance). City-wide
      // zoom now dims the whole network so the shape reads as one system;
      // any interaction (hover/selection) restores full strength. Street
      // zoom (>= 13, where lines separate) keeps the vivid 0.95 default.
      const cityOverview = zoomLevel < 13;
      const idleOpacity = cityOverview ? 0.45 : 0.95;
      const idleCasing = cityOverview ? Math.min(stroke.casingOpacity, 0.2) : stroke.casingOpacity;
      if (isCasing) {
        // Casing dims a touch when unselected so the vivid line still leads;
        // it disappears only when the map is focusing on a single route.
        cast.setStyle({
          weight: stroke.casing,
          opacity: focusRoute != null ? (hl ? 0.6 : 0.15) : idleCasing,
        });
        return;
      }
      cast.setStyle({
        weight: hl ? stroke.line + 1 : stroke.line,
        opacity: focusRoute != null ? (hl ? 1 : hoverOnly ? 0.3 : 0.12) : idleOpacity,
      });
    });
  }, [highlightedRoute, hoverRoute, zoomLevel, showProposedNetwork, optimizeShifts, circuity, useLeaflet]);

  // ---- proposed split emphasis (selected route pops) ------------------
  useEffect(() => {
    const layer = splitLayerRef.current;
    if (!layer) return;
    styleSplitLayer(layer, showProposedNetwork, highlightedRoute ?? null);
  }, [showProposedNetwork, highlightedRoute, circuity, useLeaflet]);

  // ---- proposed-network route-number badges ---------------------------
  // Show-all mode labels every proposal; focus mode labels only the selected
  // route (the panel explains it in color next to the map), keeping the calm
  // view free of badge clutter.
  useEffect(() => {
    const group = proposedLabelLayerRef.current;
    const map = mapRef.current;
    if (!group || !map || !circuity) return;
    group.clearLayers();
    // Badges only make sense when the proposed split lines are actually drawn
    // on the map — gating on the same `showSplits` flag keeps a plain route
    // highlight (Explore's "Highlight a route", Home jump-ins, optimizer
    // results) from silently rendering unexplained 35 / 35A badges.
    if (!showSplits || (!showProposedNetwork && highlightedRoute == null)) {
      map.removeLayer(group);
      return;
    }
    circuity.features.forEach((f) => {
      const p = f.properties;
      if (!p.flagged || !p.proposed_split) return;
      if (!showProposedNetwork && p.route_short_name !== highlightedRoute) return;
      const color = proposalColors.get(p.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
      // Trunk badge: solid fill in the route's color (main line).
      const parts: { label: string; color: string; coords: [number, number][]; solid: boolean }[] = [
        { label: p.route_short_name, color, coords: p.proposed_split.trunk_geometry, solid: true },
      ];
      // Feeder badges: outlined, lettered (36A, 36B, ...).
      p.proposed_split.branches.forEach((b, i) => {
        parts.push({
          label: `${p.route_short_name}${String.fromCharCode(65 + i)}`,
          color,
          coords: b.geometry,
          solid: false,
        });
      });
      parts.forEach(({ label, color, coords, solid }) => {
        if (coords.length < 2) return;
        const mid = coords[Math.floor(coords.length / 2)];
        const html = solid
          ? `<div class="proposed-route-badge-solid" style="background:${color}">${label}</div>`
          : `<div class="proposed-route-badge-inner" style="border-color:${color};color:${color}">${label}</div>`;
        const icon = L.divIcon({ className: 'proposed-route-badge', html, iconSize: [0, 0] });
        L.marker([mid[1], mid[0]], { icon, interactive: false }).addTo(group);
      });
    });
    if (!map.hasLayer(group)) group.addTo(map);
  }, [circuity, showProposedNetwork, showSplits, proposalColors, highlightedRoute, useLeaflet]);

  // ---- planned journey overlay (travel compare) -------------------------
  useEffect(() => {
    const group = travelLayerRef.current;
    const map = mapRef.current;
    if (!group || !map) return;
    group.clearLayers();

    travelLines.forEach((line) => {
      if (line.points.length < 2) return;
      const latlngs = line.points as L.LatLngTuple[];
      const poly = L.polyline(latlngs, {
        color: line.color,
        weight: line.weight ?? 4,
        opacity: 0.95,
        dashArray: line.dashArray,
      });
      poly.bindPopup(
        `<strong>${line.label}</strong><br/>Planned journey leg`
      );
      poly.addTo(group);
    });

    travelMarkers.forEach((m) => {
      const icon = L.divIcon({
        className: 'travel-point-marker',
        html: `<div class="travel-point-dot" style="background:${m.color}"></div>`,
        iconSize: [14, 14],
        iconAnchor: [7, 7],
      });
      const mk = L.marker([m.lat, m.lon], { icon });
      mk.bindPopup(`<strong>${m.label}</strong>`);
      mk.addTo(group);
    });

    if (travelLines.length || travelMarkers.length) {
      const pts: L.LatLngExpression[] = [
        ...travelLines.flatMap((l) => l.points),
        ...travelMarkers.map((m) => [m.lat, m.lon] as L.LatLngTuple),
      ];
      map.fitBounds(L.latLngBounds(pts), { padding: [40, 40], maxZoom: 15 });
    }
  }, [travelLines, travelMarkers, useLeaflet]);

  // ---- route-gaps seam overlay -----------------------------------------
  // The selected corridor seam draws its leg corridors (amber = terminating
  // leg, slate dashed = through-service leg) plus a terminal marker, and
  // zooms to fit.
  useEffect(() => {
    const group = seamLayerRef.current;
    const map = mapRef.current;
    if (!group || !map) return;
    group.clearLayers();
    if (!corridorSeam) return;

    const bounds: L.LatLngTuple[] = [];
    corridorSeam.legs.forEach((leg) => {
      const pts = leg.stops_geo
        .filter((s) => Number.isFinite(s.lat) && Number.isFinite(s.lon))
        .map((s) => [s.lat, s.lon] as L.LatLngTuple);
      if (pts.length < 2) return;
      const terminating = leg.terminates_at_terminal;
      const poly = L.polyline(pts, {
        color: terminating ? '#f59e0b' : '#94a3b8',
        weight: 5,
        opacity: 0.95,
        dashArray: terminating ? undefined : '6 5',
      });
      const first = leg.stops_geo[0];
      poly.bindPopup(
        `<strong>${corridorSeam.corridor}</strong><br/>` +
          `${leg.side} leg · routes ${leg.routes.join(', ')}` +
          (first ? `<br/>from ${first.name} outward` : '')
      );
      poly.addTo(group);
      bounds.push(...pts);
    });

    if (corridorSeam.terminal_geo) {
      const { lat, lon, name } = corridorSeam.terminal_geo;
      const icon = L.divIcon({
        className: 'seam-terminal-marker',
        html: `<div class="seam-terminal-dot"></div>`,
        iconSize: [16, 16],
        iconAnchor: [8, 8],
      });
      const mk = L.marker([lat, lon], { icon });
      mk.bindPopup(`<strong>${name}</strong><br/>corridor seam`);
      mk.addTo(group);
      bounds.push([lat, lon]);
    }

    if (bounds.length) {
      // The container can be resized by React layout without a window resize
      // event (sidebar / panel switches), so Leaflet's internal size goes
      // stale and fitBounds computes the wrong zoom - re-measure first.
      map.invalidateSize();
      map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50], maxZoom: 16 });
    }
  }, [corridorSeam, useLeaflet]);

  // ---- optimizer re-phase overlay -------------------------------------
  // After the solver runs, the routes it moved draw in direction colors
  // (blue = runs earlier, amber = runs later) with a badge showing the signed
  // offset, so the "what changed" view renders on the map without needing the
  // travel planner. The base network is dimmed by the highlight effect above.
  useEffect(() => {
    const group = shiftLayerRef.current;
    if (!group) return;
    group.clearLayers();
    if (optimizeShifts.length === 0) return;
    const byRoute = new Map(
      (circuity?.features ?? []).map((f) => [f.properties.route_short_name, f])
    );
    optimizeShifts.forEach((s) => {
      const f = byRoute.get(s.route_short_name);
      if (!f) return;
      const coords = f.geometry.coordinates as [number, number][];
      if (coords.length < 2) return;
      const latlngs = coords.map(([lon, lat]) => [lat, lon] as L.LatLngTuple);
      const earlier = s.offset_minutes < 0;
      const color = earlier ? SHIFT_EARLIER_COLOR : SHIFT_LATER_COLOR;
      const weight = 2.5 + Math.min(4, Math.abs(s.offset_minutes));
      const poly = L.polyline(latlngs, { color, weight, opacity: 1 });
      poly.bindPopup(
        `<strong>Route ${s.route_short_name}</strong><br/>` +
          `moved ${earlier ? 'earlier' : 'later'} by ${Math.abs(s.offset_minutes)} min`
      );
      poly.addTo(group);
      // Offset badge at the route's midpoint: "R42 +4m" / "R5 -3m".
      const mid = coords[Math.floor(coords.length / 2)];
      const label = `R${s.route_short_name} ${earlier ? '-' : '+'}${Math.abs(s.offset_minutes)}m`;
      const icon = L.divIcon({
        className: 'proposed-route-badge',
        html: `<div class="optimize-shift-badge" style="background:${color}">${label}</div>`,
        iconSize: [0, 0],
      });
      L.marker([mid[1], mid[0]], { icon, interactive: false }).addTo(group);
    });
}, [circuity, optimizeShifts, useLeaflet]);

   // ---- ward equity overlay -------------------------------------
   // Colors wards based on equity score (delta_minutes from equity report)
   useEffect(() => {
     const layer = wardLayerRef.current;
     const map = mapRef.current;
     if (!layer || !map || !wardBoundaries) return;

     // Clear existing layers
     layer.clearLayers();

     // If we have ward boundaries and scores, add them to the layer
     if (wardBoundaries && Object.keys(wardScores).length > 0) {
       layer.addData(wardBoundaries);
     }

     // Show/hide based on toggle
     if (showWardScores) {
       if (!map.hasLayer(layer)) {
         layer.addTo(map);
       }
     } else {
       map.removeLayer(layer);
     }
   }, [wardBoundaries, wardScores, showWardScores, useLeaflet]);

   // ---- map click -> pick a point (travel planner) ----------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !onMapPick) return;
    const handler = (e: L.LeafletMouseEvent) => onMapPick(e.latlng.lat, e.latlng.lng);
    map.on('click', handler);
    return () => {
      map.off('click', handler);
    };
  }, [onMapPick, useLeaflet]);

  if (!useLeaflet) {
    return (
      <FallbackSvg
        circuity={circuity}
        nodes={nodes}
        showRoutes={showRoutes}
        showSplits={showSplits}
        showNodes={showNodes}
        showOneWay={showOneWay}
        travelLines={travelLines}
        travelMarkers={travelMarkers}
        onMapPick={onMapPick}
        pickActive={pickActive}
      />
    );
  }

  return (
    <div className="relative h-full w-full">
      <div
        ref={containerRef}
        className={`h-full w-full ${pickActive ? 'cursor-crosshair' : ''}`}
        style={{ background: '#1E1E1E' }}
      />
{/* Circuity key — swatches call circuityColor so map and key can never drift.
     Only shown when circuity-colored routes are actually drawn (A24: the
     Trunk & feeder view draws route-hue trunk/branch lines, not circuity
     colors — this legend described a coloring that wasn't on screen).
     A20: chrome uses the app's dark card tokens, not white chips. */}
{showRoutes && circuity && !showSplits && optimizeShifts.length === 0 && (
<div className="pointer-events-none absolute bottom-7 left-2 z-[1000] rounded-lg border border-border bg-card/95 px-2.5 py-1.5 text-[10px] leading-4 text-text-secondary shadow-sm">
  <div className="font-semibold text-text-primary">How winding is the route?</div>
  <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1">
    {LEGEND_STOPS.map((s) => (
      <span key={s.label} className="flex items-center gap-1">
        <span
          className="inline-block h-1.5 w-4 rounded-lg"
          style={{ background: circuityColor(s.c) }}
        />
        {s.label}
      </span>
    ))}
  </div>
</div>
)}
<div className="pointer-events-none absolute left-2 top-2 z-[1000] flex items-center gap-2 rounded-lg border border-border bg-card/95 px-2 py-1 text-[10px] text-text-secondary shadow-sm">
  Leaflet · {basemap.label}{tileNote ? ` · ${tileNote}` : ''}
  <BasemapPicker className="-my-1" />
  {wardLayerError ? (
    <span className="ml-1 cursor-not-allowed opacity-50" title="Ward boundaries could not be loaded — the overlay is unavailable">
      · Ward scores: unavailable
    </span>
  ) : (
    <button
      type="button"
      onClick={() => setShowWardScores(!showWardScores)}
      aria-pressed={showWardScores}
      title="Color wards by the equity report's rider-time delta"
      className={`ml-1 rounded border px-1.5 py-px text-[10px] transition-colors ${ showWardScores ? 'border-accent/60 bg-accent/15 text-accent' : 'border-border text-text-muted hover:bg-card-hover hover:text-text-secondary' }`}
    >
      Ward scores: {showWardScores ? 'on' : 'off'}
    </button>
  )}
  {optimizeShifts.length > 0 && (
    <span className="ml-1">
      · <span style={{ color: SHIFT_EARLIER_COLOR }}>●</span> earlier{' '}
      <span style={{ color: SHIFT_LATER_COLOR }}>●</span> later
    </span>
  )}
</div>
    </div>
  );
}
